"""Single-attempt submission with mandatory platform reconciliation."""

from __future__ import annotations

import hashlib
import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from enum import Enum
from pathlib import Path
from typing import Any, Protocol


class SubmissionGateway(Protocol):
    def fetch_alpha(self, alpha_id: str) -> dict[str, Any]: ...
    def submit_alpha(self, alpha_id: str) -> dict[str, Any]: ...


class SubmissionStatus(str, Enum):
    NOT_EXECUTED = "NOT_EXECUTED"
    VERIFIED = "VERIFIED"
    UNCERTAIN = "UNCERTAIN"
    FAILED = "FAILED"


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


@dataclass(frozen=True)
class SubmissionResult:
    status: SubmissionStatus
    intent_id: str
    error: str = ""


class SubmissionDelivery:
    def __init__(self, database: str | Path, gateway: SubmissionGateway) -> None:
        self.database = Path(database)
        self.gateway = gateway

    def _intent(self, sync_id: str, alpha_id: str) -> tuple[str, str | None]:
        payload_hash = hashlib.sha256(b"submit-once").hexdigest()
        intent_id = hashlib.sha256(
            f"{sync_id}\0{alpha_id}\0SUBMIT\0{payload_hash}".encode("utf-8")
        ).hexdigest()
        now = _utc_now()
        with sqlite3.connect(self.database) as con:
            con.execute(
                """INSERT OR IGNORE INTO platform_write_intents
                (intent_id,sync_id,alpha_id,operation,payload_hash,status,attempt_count,created_at,updated_at)
                VALUES (?,?,?,?,?,'PENDING',0,?,?)""",
                (intent_id, sync_id, alpha_id, "SUBMIT", payload_hash, now, now),
            )
            row = con.execute(
                "SELECT status FROM platform_write_intents WHERE intent_id=?", (intent_id,)
            ).fetchone()
        return intent_id, str(row[0]) if row else None

    def submit_once(
        self, *, sync_id: str, alpha_id: str, execute: bool
    ) -> SubmissionResult:
        if not execute:
            return SubmissionResult(SubmissionStatus.NOT_EXECUTED, "")
        intent_id, existing = self._intent(sync_id, alpha_id)
        if existing == "CONFIRMED":
            return SubmissionResult(SubmissionStatus.VERIFIED, intent_id)
        before = self.gateway.fetch_alpha(alpha_id)
        before_status = str(before.get("status") or "UNKNOWN").upper()
        if before_status in {"SUBMITTED", "ACTIVE", "PRODUCTION"}:
            self._finish(intent_id, "CONFIRMED", None, "")
            return SubmissionResult(SubmissionStatus.VERIFIED, intent_id)
        if before_status != "UNSUBMITTED" or existing in {"PROCESSING", "UNCERTAIN"}:
            return SubmissionResult(SubmissionStatus.UNCERTAIN, intent_id, f"platform status {before_status}")
        with sqlite3.connect(self.database) as con:
            con.execute(
                """UPDATE platform_write_intents SET status='PROCESSING',attempt_count=attempt_count+1,
                   updated_at=? WHERE intent_id=? AND status='PENDING'""",
                (_utc_now(), intent_id),
            )
        error = ""
        http_status: int | None = None
        try:
            response = self.gateway.submit_alpha(alpha_id)
            http_status = int(response.get("status_code") or 0)
        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"
        after = self.gateway.fetch_alpha(alpha_id)
        after_status = str(after.get("status") or "UNKNOWN").upper()
        if after_status in {"SUBMITTED", "ACTIVE", "PRODUCTION"}:
            self._finish(intent_id, "CONFIRMED", http_status, error)
            return SubmissionResult(SubmissionStatus.VERIFIED, intent_id, error)
        if error:
            self._finish(intent_id, "UNCERTAIN", http_status, error, complete=False)
            return SubmissionResult(SubmissionStatus.UNCERTAIN, intent_id, error)
        self._finish(intent_id, "FAILED", http_status, f"platform status {after_status}")
        return SubmissionResult(
            SubmissionStatus.FAILED, intent_id, f"platform status {after_status}"
        )

"""The only production network gateway for simulate/check/PATCH/Submit."""

from __future__ import annotations

import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable
from urllib.parse import urljoin

from .client import BASE_URL, PlatformReadError, ReadOnlyPlatformClient
from .protocol import alpha_id_from_progress, extract_checks, extract_metrics


@dataclass
class PlatformGateway:
    state_path: str | Path = ".wq_auth_state.json"
    database: str | Path = "research_memory.sqlite"
    lock_path: str | Path = "worldquant_api.lock"
    timeout: float = 30.0
    min_interval: float = 2.0
    poll_interval: float = 2.0
    max_poll_seconds: float = 600.0
    sleeper: Callable[[float], None] = time.sleep

    def __post_init__(self) -> None:
        self.client = ReadOnlyPlatformClient(
            state_path=self.state_path,
            timeout=self.timeout,
            min_interval=self.min_interval,
            database=self.database,
            lock_path=self.lock_path,
            sleeper=self.sleeper,
        )

    def authenticate(self) -> None:
        self.client.authenticate()

    def fetch_alpha(self, alpha_id: str) -> dict[str, Any]:
        return self.client.fetch_alpha(alpha_id)

    def patch_alpha(self, alpha_id: str, payload: dict[str, Any]) -> dict[str, Any]:
        response = self.client.request(
            "PATCH",
            f"{BASE_URL}/alphas/{alpha_id}",
            json=payload,
            endpoint_class="description_patch",
            allow_server_retry=False,
        )
        if response.status_code not in {200, 201, 204}:
            raise PlatformReadError(f"description PATCH failed with HTTP {response.status_code}")
        return {"status_code": int(response.status_code)}

    def submit_alpha(self, alpha_id: str) -> dict[str, Any]:
        response = self.client.request(
            "POST",
            f"{BASE_URL}/alphas/{alpha_id}/submit",
            endpoint_class="submit",
            allow_server_retry=False,
        )
        if response.status_code not in {200, 201, 202}:
            raise PlatformReadError(f"submit failed with HTTP {response.status_code}")
        return {"status_code": int(response.status_code)}

    def simulate(
        self, *, expression: str, settings: dict[str, Any], alpha_type: str = "REGULAR"
    ):
        from alpha_mining.factory.orchestrator import SimulationResult

        self.authenticate()
        kind = str(alpha_type or "REGULAR").upper()
        payload: dict[str, Any] = {"type": kind, "settings": dict(settings)}
        if kind == "REGULAR":
            payload["regular"] = expression
        else:
            payload["expression"] = expression
        response = self.client.request(
            "POST",
            f"{BASE_URL}/simulations",
            json=payload,
            endpoint_class="simulation_submit",
            allow_server_retry=False,
        )
        if response.status_code not in {200, 201, 202}:
            raise PlatformReadError(f"simulation submit failed with HTTP {response.status_code}")
        try:
            body = response.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        alpha_id = alpha_id_from_progress(body)
        location = str(response.headers.get("Location") or "").strip()
        if not alpha_id and not location:
            raise PlatformReadError("simulation response has no alpha id or progress location")
        if not alpha_id:
            progress_url = location if location.startswith("http") else urljoin(f"{BASE_URL}/", location.lstrip("/"))
            deadline = time.monotonic() + max(1.0, float(self.max_poll_seconds))
            while time.monotonic() < deadline:
                progress = self.client.request(
                    "GET", progress_url, endpoint_class="simulation_poll"
                )
                if progress.status_code != 200:
                    raise PlatformReadError(f"simulation poll failed with HTTP {progress.status_code}")
                try:
                    current = progress.json()
                except Exception:
                    current = {}
                current = current if isinstance(current, dict) else {}
                state = str(current.get("status") or current.get("state") or "").upper()
                if state in {"FAILED", "ERROR", "REJECTED"}:
                    return SimulationResult("", state, {}, extract_checks(current), current)
                alpha_id = alpha_id_from_progress(current)
                if alpha_id:
                    body = current
                    break
                self.sleeper(max(0.1, float(self.poll_interval)))
            if not alpha_id:
                raise PlatformReadError("simulation poll timed out without alpha id")
        detail = self.fetch_alpha(alpha_id)
        return SimulationResult(
            alpha_id=alpha_id,
            status="COMPLETE",
            metrics=extract_metrics(detail),
            checks=extract_checks(detail),
            raw=detail,
        )

"""Fail-closed submission guard for consultant candidates."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from typing import Any

PASS = "PASS"


@dataclass(frozen=True)
class CandidateContext:
    alpha_id: str
    expression_id: str
    checks: list[dict[str, Any]]
    gate_snapshots_fresh: bool
    quality_buffer_pass: bool
    local_correlation_status: str
    unit_warnings: tuple[str, ...] = ()
    concentration_failure: bool = False
    duplicate: bool = False
    submitted_cluster: bool = False
    mandatory_checks: tuple[str, ...] = ("LOW_SHARPE",)
    competition_required: bool = False
    theme_required: bool = False
    pyramid_required: bool = False
    metrics: dict[str, float] = field(default_factory=dict)
    ledger_status: str = ""
    ledger_synced_at: str = ""
    ledger_sync_id: str = ""
    candidate_sync_id: str = ""
    ledger_freshness_hours: float = 24.0
    description_valid: bool = True
    platform_status: str = "UNSUBMITTED"
    description_status: str = ""
    prod_correlation_required: bool = False
    prod_corr_exception_confirmed: bool = False
    write_intent_statuses: tuple[str, ...] = ()
    execute_submit_enabled: bool | None = None


@dataclass(frozen=True)
class GuardDecision:
    allowed: bool
    reasons: tuple[str, ...]


class SubmissionGuard:
    def evaluate(self, context: CandidateContext) -> GuardDecision:
        reasons: list[str] = []
        by_name = {
            str(check.get("name") or "").upper(): str(
                check.get("result") or check.get("status") or "UNKNOWN"
            ).upper()
            for check in context.checks
            if isinstance(check, dict)
        }
        if not by_name:
            reasons.append("CHECKS_MISSING")
        mandatory = {name.upper() for name in context.mandatory_checks}
        mandatory.update(
            str(check.get("name") or "").upper()
            for check in context.checks
            if isinstance(check, dict) and check.get("mandatory") is True
        )
        for name in sorted(mandatory):
            status = by_name.get(name.upper(), "MISSING")
            if status != PASS:
                reasons.append(f"MANDATORY_{name.upper()}_{status}")
        self_status = by_name.get("SELF_CORRELATION", "MISSING")
        if self_status != PASS:
            reasons.append(f"SELF_CORRELATION_{self_status}")
        if context.prod_correlation_required:
            prod_status = by_name.get(
                "PROD_CORRELATION", by_name.get("PRODUCTION_CORRELATION", "MISSING")
            )
            if prod_status != PASS and not context.prod_corr_exception_confirmed:
                reasons.append(f"PROD_CORRELATION_{prod_status}")
        for required, name in (
            (context.competition_required, "MATCHES_COMPETITION"),
            (context.theme_required, "MATCHES_THEME"),
            (context.pyramid_required, "MATCHES_PYRAMID"),
        ):
            if required and by_name.get(name, "MISSING") != PASS:
                reasons.append(f"{name}_{by_name.get(name, 'MISSING')}")
        for name, status in by_name.items():
            # Unknown future checks are fail-closed too: only an explicit PASS is complete.
            if status != PASS and not any(
                reason.startswith(name) or name in reason for reason in reasons
            ):
                reasons.append(f"CHECK_{name or 'UNKNOWN'}_{status}")
        if not context.gate_snapshots_fresh:
            reasons.append("GATE_SNAPSHOT_STALE_OR_MISSING")
        if not context.quality_buffer_pass:
            reasons.append("QUALITY_BUFFER_FAILED")
        local = context.local_correlation_status.upper()
        if local == "INSUFFICIENT_HISTORY":
            reasons.append("LOCAL_CORRELATION_INSUFFICIENT_HISTORY")
        elif local != "PASS":
            reasons.append(f"LOCAL_CORRELATION_{local or 'MISSING'}")
        if context.unit_warnings:
            reasons.append("UNIT_WARNING")
        if context.concentration_failure:
            reasons.append("CONCENTRATION_FAILURE")
        if context.duplicate:
            reasons.append("DUPLICATE")
        if context.submitted_cluster:
            reasons.append("SUBMITTED_CLUSTER")
        if context.description_status and context.description_status.upper() not in {
            "VERIFIED",
            "NOT_REQUIRED",
        }:
            reasons.append("DESCRIPTION_NOT_VERIFIED")
        elif not context.description_valid:
            reasons.append("DESCRIPTION_INVALID_OR_MISSING")
        if str(context.platform_status or "UNKNOWN").upper() != "UNSUBMITTED":
            reasons.append(f"PLATFORM_STATUS_{str(context.platform_status or 'UNKNOWN').upper()}")
        for write_status in context.write_intent_statuses:
            normalized = str(write_status or "UNKNOWN").upper()
            if normalized in {"PENDING", "PROCESSING", "UNCERTAIN", "UNKNOWN"}:
                reasons.append(f"WRITE_INTENT_{normalized}")
        if context.execute_submit_enabled is False:
            reasons.append("EXECUTE_SUBMIT_DISABLED")
        ledger_fresh = context.ledger_status.upper() == "COMPLETE"
        try:
            synced = datetime.fromisoformat(context.ledger_synced_at.replace("Z", "+00:00"))
            if synced.tzinfo is None:
                synced = synced.replace(tzinfo=timezone.utc)
            ledger_fresh = ledger_fresh and synced >= datetime.now(timezone.utc) - timedelta(hours=context.ledger_freshness_hours)
        except (AttributeError, TypeError, ValueError):
            ledger_fresh = False
        if not ledger_fresh:
            reasons.append("PLATFORM_LEDGER_STALE_OR_MISSING")
        if not context.ledger_sync_id or not context.candidate_sync_id:
            reasons.append("PLATFORM_LEDGER_SYNC_MISSING")
        elif context.ledger_sync_id != context.candidate_sync_id:
            reasons.append("PLATFORM_LEDGER_SYNC_MISMATCH")
        return GuardDecision(not reasons, tuple(dict.fromkeys(reasons)))

